static uint32_t z_t1968_entries_cap(uint32_t _capacity) {
    return (uint32_t)((((uint64_t)_capacity) * 2u) / 3u);
}

static void z_t1968_destroy(z_t1968_t* p);
static void z_t1968_destroy(z_t1968_t* p) {
    if (!p) return;
    free(p->indices);
    free(p->entries);
    /* NO free(p) -- the struct is on the stack */
}

